courses=[dict(id='de',name='გერმანული',subtitle='საუბარი ყოველდღიურ ცხოვრებაში',flag='🇩🇪',tag='Deutsch',level='A1',color='violet',lessonCount=len(modules)),dict(id='en',name='ინგლისური',subtitle='საწყისი სასაუბრო ინგლისური',flag='🇬🇧',tag='English',level='A1',color='blue',lessonCount=len(english))]
words=[];lessons=[]
for course_id,entries in [('de',modules),('en',english)]:
 for idx,(mid,title,summary,goal,terms,grammar,dialogue) in enumerate(entries,1):
  ids=[]
  for j,(term,phonetic,translation,ex,exka) in enumerate(terms,1):
   id=f'{mid}-w{j:02}';ids.append(id)
   words.append(dict(id=id,course_id=course_id,lesson_id=mid,term=term,phonetic=phonetic,translation=translation,example=ex,example_ge=exka,level='A1',order=j))
  lessons.append(dict(id=mid,course_id=course_id,order=idx,level='A1',title=title,summary=summary,goal=goal,word_ids=ids,grammar=grammar,dialogue=[dict(speaker=s,text=t,translation=tr)for s,t,tr in dialogue],xp=40))
(root/'courses.json').write_text(json.dumps(courses,ensure_ascii=False,indent=2),encoding='utf8')
(root/'words.json').write_text(json.dumps(words,ensure_ascii=False,indent=2),encoding='utf8')
(root/'lessons.json').write_text(json.dumps(lessons,ensure_ascii=False,indent=2),encoding='utf8')
